<div class="page-head"><div><span class="eyebrow">Provider Management</span><h1><?=e($title)?></h1><p>Provider profiles are separate from user accounts. Link a user only when that provider should access their own scorecard.</p></div><a class="btn btn-secondary" href="<?=url('business-provider-kpi-providers')?>">Back</a></div>
<form method="post" class="panel form-panel"><?=csrf_field()?><div class="form-grid two"><label>Provider name<input name="name" required maxlength="160" value="<?=e($_POST['name']??$provider['name']??'')?>"></label><label>Provider email<input type="email" name="email" maxlength="190" value="<?=e($_POST['email']??$provider['email']??'')?>"></label><label>Provider type<input name="provider_type" placeholder="NP, RN, PA, MD, Esthetician, Wellness…" maxlength="100" value="<?=e($_POST['provider_type']??$provider['provider_type']??'')?>"></label><label>Department<input name="department" maxlength="120" value="<?=e($_POST['department']??$provider['department']??'')?>"></label><label>Linked business user<select name="linked_user_id"><option value="">Not linked</option><?php foreach($businessUsers as $u):?><option value="<?=$u['id']?>" <?=(string)($_POST['linked_user_id']??$provider['linked_user_id']??'')===(string)$u['id']?'selected':''?>><?=e($u['name'])?> · <?=e($u['email'])?></option><?php endforeach;?></select><small>Linking a user automatically grants Provider-only KPI access.</small></label><label>Status<select name="status"><option value="active" <?=($_POST['status']??$provider['status']??'active')==='active'?'selected':''?>>Active</option><option value="inactive" <?=($_POST['status']??$provider['status']??'')==='inactive'?'selected':''?>>Inactive</option></select></label><label>Display order<input type="number" min="0" max="999" name="display_order" value="<?=e($_POST['display_order']??$provider['display_order']??0)?>"></label></div><button class="btn btn-primary" type="submit">Save Provider</button></form>
